import type { SVGAttributes } from 'react';
import { cn } from '../../utils/cn';

export interface SpinnerProps extends SVGAttributes<SVGSVGElement> {
  size?: number;
  /** Accessible label. Without it the spinner is decorative (aria-hidden). */
  label?: string;
}

/** Indeterminate loading indicator; inherits currentColor. */
export function Spinner({ size = 16, label, className, ...props }: SpinnerProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      className={cn('block shrink-0 animate-spin motion-reduce:animate-[spin_1.6s_linear_infinite]', className)}
      role={label ? 'status' : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      {...props}
    >
      <circle cx="12" cy="12" r="9" fill="none" stroke="currentColor" strokeWidth="2.6" strokeOpacity="0.25" />
      <path d="M21 12a9 9 0 0 0-9-9" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" />
    </svg>
  );
}

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'Spinner',
  group: 'Feedback',
  status: 'stable',
  description: 'Indeterminate loading indicator that inherits the current text colour.',
  pattern: 'status',
  tokens: ['currentColor'],
};

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
